import{_ as s,o as n,c as e,a2 as p}from"./chunks/framework.CHeM0PsO.js";const b=JSON.parse('{"title":"点歌与音乐登录","description":"","frontmatter":{},"headers":[],"relativePath":"projects/lotus-plugin/docs/music.md","filePath":"projects/lotus-plugin/docs/music.md"}'),l={name:"projects/lotus-plugin/docs/music.md"};function c(r,a,i,t,o,d){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="点歌与音乐登录" tabindex="-1">点歌与音乐登录 <a class="header-anchor" href="#点歌与音乐登录" aria-label="Permalink to &quot;点歌与音乐登录&quot;">​</a></h1><p>返回：<a href="./../README.html">项目主页</a> / <a href="./README.html">文档目录</a></p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#点歌 歌名</span></span>
<span class="line"><span>#网易点歌 歌名</span></span>
<span class="line"><span>#QQ点歌 歌名</span></span>
<span class="line"><span>#酷狗点歌 歌名</span></span>
<span class="line"><span>#酷我点歌 歌名</span></span>
<span class="line"><span>#咪咕点歌 歌名</span></span>
<span class="line"><span>#汽水点歌 歌名</span></span>
<span class="line"><span>#下一页</span></span>
<span class="line"><span>#听1</span></span>
<span class="line"><span>#取消</span></span>
<span class="line"><span>#音乐登录</span></span>
<span class="line"><span>#音乐帮助</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>默认搜索网易云，也支持 <code>#搜歌</code> 和 <code>#荷花点歌</code>。搜索列表按平台分开，输入数字选歌；两分钟内有效，按机器人、会话与发起用户隔离。音乐、视频搜索和登录的数字选择不会共用列表。</p><p>选歌后默认发送音乐卡片和完整语音。卡片标识与跳转地址使用搜索时选定的平台，备用音源不改变卡片来源。播放通过 TuneWeave 明确启用多音源回退与 unblock，搜索平台不限制备用音源。无法获得完整音频时会提示登录，不把试听片段当成整首歌。平台没有对应卡片类型、当前适配器不支持或媒体地址需要私有请求头时，回退为图片信息卡与语音。</p><h2 id="主人扫码登录" tabindex="-1">主人扫码登录 <a class="header-anchor" href="#主人扫码登录" aria-label="Permalink to &quot;主人扫码登录&quot;">​</a></h2><p>公共音乐账号仅机器人主人维护。发送 <code>#音乐登录</code>，先选择平台；存在多种二维码时再输入方式序号，例如 QQ、QQ音乐、微信，然后出码。当前可扫码平台由 TuneWeave 能力决定，不提供二维码的平台仍可尝试匿名搜索与播放。</p><p>网易云与 <code>#合伙人登录</code> 共用登录服务和账号引用；新扫码同时更新点歌账号，不重复创建凭证。仅有一个既有合伙人账号引用时自动接续；多个账号时请主人通过扫码明确当前公共账号。</p><p>登录由 TuneWeave 托管，同时保存供跨平台回退使用的不透明凭证。Lotus 本地数据只写入 <code>data/music/</code>；凭据不展示在消息或配置面板中，轮换后自动更新。不要公开或提交该目录。</p><h2 id="配置与适配器" tabindex="-1">配置与适配器 <a class="header-anchor" href="#配置与适配器" aria-label="Permalink to &quot;配置与适配器&quot;">​</a></h2><p>锅巴和 <code>#荷花面板</code> 共用默认平台、音质、列表长度、超时与体积上限等配置。默认使用标准音质（<code>standard</code>），完整音频会转为语音使用的单声道 WAV 后发送。已有配置若明确保存了 <code>auto</code>，可在音乐音质设置中改为 <code>standard</code>。</p><p>语音显示实际时长；已移除无效的一秒显示配置。音乐卡片依赖适配器自身支持，NapCat 的音乐签名服务不可用时会回退图片卡。</p>`,12)])])}const m=s(l,[["render",c]]);export{b as __pageData,m as default};
